import json
from pathlib import Path

# Extract full new_string blocks from the historical log
log = Path('/home/hello19y/openvela/contest2026_004_TeamFalcons/logs/Foleaf/2026-08-17/cursor__57f39c16-c9a7-425e-95ea-ce64e47ca185.jsonl')
blocks = {}
for line in log.read_text().splitlines():
    ev = json.loads(line)
    inp = ev.get('input') or {}
    if not isinstance(inp, dict):
        continue
    path = inp.get('path', '')
    if not path.endswith('snapshot_core.py'):
        continue
    seq = ev.get('seq')
    if 'new_string' in inp and 'old_string' in inp:
        blocks[seq] = (inp['old_string'], inp['new_string'])

base_path = Path('/home/hello19y/openvela/.claude/skills/contest-log-collector/adapters/shared/snapshot_core.py')
text = base_path.read_text()

# Apply patches in order, skipping ones whose old_string is absent
for seq in sorted(blocks):
    old, new = blocks[seq]
    if old in text:
        text = text.replace(old, new, 1)
        print('applied', seq)
    else:
        print('skip', seq, 'old not found')

# Manual fixes for base differences (no grok in current tree)
text = text.replace('from datetime import datetime, timezone', 'from datetime import datetime, timedelta, timezone')
if 'VERSION = "1.3.0"' in text:
    text = text.replace('VERSION = "1.3.0"', 'VERSION = "1.4.0"')
if 'SUPPORTED_TOOLS' not in text:
    text = text.replace('SCHEMA_VERSION = "1.0"\n\nDEFAULT_REDACT_RULES', 'SCHEMA_VERSION = "1.0"\nSUPPORTED_TOOLS = ("claude-code", "codex", "cursor")\n\nDEFAULT_REDACT_RULES')
if 'CURSOR_SKIP_TYPES' not in text:
    text = text.replace('SKIP_BLOCK_TYPES = {"image"}\n\n\ndef iso_now', 'SKIP_BLOCK_TYPES = {"image"}\nCURSOR_SKIP_TYPES = {"turn_ended", "progress", "file-history-snapshot"}\n_CURSOR_TS_RE = re.compile(r"<timestamp>\\s*(.*?)\\s*</timestamp>", re.DOTALL)\n_CURSOR_TZ_RE = re.compile(r"\\(UTC([+-])(\\d+)(?::(\\d+))?\\)\\s*$")\n\n\ndef iso_now')

# get_repo_root(cwd) used by cursor handler
if 'def get_repo_root() -> Path | None:' in text:
    text = text.replace(
        'def get_repo_root() -> Path | None:\n    try:\n        out = subprocess.check_output(["git", "rev-parse", "--show-toplevel"], stderr=subprocess.PIPE, text=True)\n        return Path(out.strip())\n    except Exception:\n        return None',
        'def get_repo_root(start_dir: str | Path | None = None) -> Path | None:\n    try:\n        out = subprocess.check_output(\n            ["git", "rev-parse", "--show-toplevel"],\n            stderr=subprocess.PIPE,\n            text=True,\n            cwd=str(start_dir) if start_dir else None,\n        )\n        return Path(out.strip())\n    except Exception:\n        return None'
    )

# main() choices and routing
text = text.replace(
    'parser.add_argument("--tool", required=True, choices=["claude-code", "codex"])',
    'parser.add_argument("--tool", required=True, choices=list(SUPPORTED_TOOLS))'
)
if 'if args.tool == "cursor"' not in text:
    text = text.replace(
        '    return process_claude_stdin(stdin_data, args.tool, team_id)',
        '    if args.tool == "cursor" or is_cursor_payload(stdin_data):\n        return process_cursor_stdin(stdin_data, "cursor", team_id)\n    return process_claude_stdin(stdin_data, args.tool, team_id)'
    )

# cursor detection in claude path
if 'is_cursor_payload(stdin_data)' not in text.split('def process_claude_stdin')[1].split('session_id =')[0]:
    text = text.replace(
        '    Codex Stop hook stdin payload schema is shared with Claude Code (sso_id/cwd/transcript_path use the same names).\n    """\n    session_id = stdin_data.get("session_id")',
        '    Codex Stop hook stdin payload schema is shared with Claude Code (sso_id/cwd/transcript_path use the same names).\n    """\n    if is_cursor_payload(stdin_data):\n        return process_cursor_stdin(stdin_data, "cursor", team_id)\n\n    session_id = stdin_data.get("session_id")'
    )

out = Path('/tmp/snapshot_core_patched.py')
out.write_text(text)
print('written', out, 'lines', len(text.splitlines()))
print('has cursor helpers:', all(x in text for x in ['is_cursor_payload', 'expand_cursor_event', 'process_cursor_stdin', 'find_cursor_transcript']))
